using UnityEngine;

namespace TruckSim.Audio
{
    /// <summary>
    /// A grid of seamless engine loops: rpm points x load layers (one perspective: exterior or cab).
    /// Generated by tools/audio/render_all.py; values for <see cref="clipRpmExact"/> and
    /// <see cref="clipCycles"/> come from art-source/audio/generated/manifest.json.
    /// Engine-brake banks use a single load layer (loadPoints = { 0 }).
    /// </summary>
    [CreateAssetMenu(menuName = "TruckSim/Audio/Engine Sound Bank", fileName = "EngineSoundBank")]
    public sealed class EngineSoundBank : ScriptableObject
    {
        [Tooltip("Ascending nominal rpm of each column, e.g. 600, 700 ... 2100.")]
        public float[] rpmPoints = new float[0];

        [Tooltip("Ascending load of each layer, e.g. 0 (off), 0.4 (mid), 1 (on).")]
        public float[] loadPoints = { 0f };

        [Tooltip("Clips, index = loadIndex * rpmPoints.Length + rpmIndex. Import as: Load Type = Compressed In Memory, ADPCM, loop.")]
        public AudioClip[] clips = new AudioClip[0];

        [Tooltip("Exact rpm each loop was rendered at (same indexing as clips). Pitch = rpm / clipRpmExact.")]
        public float[] clipRpmExact = new float[0];

        [Tooltip("Whole 720-degree engine cycles in each loop (same indexing). Used for crank-phase alignment.")]
        public int[] clipCycles = new int[0];

        [Tooltip("0 = 2D (cab), 1 = fully 3D (exterior, source on the engine bay).")]
        [Range(0f, 1f)] public float spatialBlend = 1f;

        [Tooltip("Cells are unrelated recordings (ElevenLabs, ADR 0137): crossfade equal-power, no crank-phase alignment.")]
        public bool incoherent;

        public int RpmCount => rpmPoints.Length;
        public int LoadCount => loadPoints.Length;

        /// <summary>Editor/boot-time validation. Allocates the error string only on failure.</summary>
        public bool Validate(out string error)
        {
            int n = rpmPoints.Length * loadPoints.Length;
            if (rpmPoints.Length == 0 || loadPoints.Length == 0) { error = name + ": empty grid"; return false; }
            if (clips.Length != n || clipRpmExact.Length != n || clipCycles.Length != n)
            {
                error = name + ": clips/clipRpmExact/clipCycles must have rpmPoints*loadPoints entries";
                return false;
            }
            for (int i = 1; i < rpmPoints.Length; i++)
                if (rpmPoints[i] <= rpmPoints[i - 1]) { error = name + ": rpmPoints not ascending"; return false; }
            for (int i = 1; i < loadPoints.Length; i++)
                if (loadPoints[i] <= loadPoints[i - 1]) { error = name + ": loadPoints not ascending"; return false; }
            for (int i = 0; i < n; i++)
            {
                if (clips[i] == null) { error = name + ": missing clip " + i; return false; }
                if (clipCycles[i] <= 0 || clipRpmExact[i] <= 0f) { error = name + ": bad loop metadata " + i; return false; }
            }
            error = null;
            return true;
        }
    }
}
